cat > /tmp/DecimalMoneyFinal.php <<'EOF'
<?php

declare(strict_types=1);

namespace App\Domain\Money;

/**
 * Immutable decimal amount, backed by BCMath exact arithmetic.
 *
 * Internally the value is a canonical decimal string with at most
 * {@see ROUND_SCALE} digits after the point (bcmath, scale 6). float is
 * intentionally never used anywhere in money paths.
 *
 * Invariants:
 *  - add()/multiply()/divideByInteger() are exact on their domain inputs
 *    (rates have ≤ 6 digits, token counts are integers, the off-peak
 *    multiplier has ≤ 6 digits, token sums fit in 64-bit integers);
 *  - rounding to 6 fractional digits is the ONLY rounding step, done
 *    HALF_UP (2.5 → 3) on the exact value.
 */
final class DecimalMoney
{
    /** The single rounding scale of the domain: 6 digits after the point. */
    public const ROUND_SCALE = 6;

    /** @var string canonical decimal value, e.g. "14.262499" or "-0.5" */
    private readonly string $value;

    private function __construct(string $value)
    {
        $this->value = bcadd($value, '0', self::ROUND_SCALE);
    }

    public static function fromDecimalString(string $value): self
    {
        $value = trim($value);
        if (preg_match('/^-?(0|[1-9]\d*)(\.\d+)?$/', $value) !== 1) {
            throw new \InvalidArgumentException(sprintf('Invalid decimal value: "%s"', $value));
        }

        return new self($value);
    }

    public static function zero(): self
    {
        return new self('0');
    }

    public function isZero(): bool
    {
        return bccomp($this->value, '0', 0) === 0;
    }

    public function isNegative(): bool
    {
        return str_starts_with($this->value, '-');
    }

    public function add(self $other): self
    {
        return new self(bcadd($this->value, $other->value, self::ROUND_SCALE));
    }

    public function subtract(self $other): self
    {
        return new self(bcsub($this->value, $other->value, self::ROUND_SCALE));
    }

    /** Exact product (no rounding): operands have ≤ 6 digits ⇒ result ≤ 12, exact. */
    public function multiply(self $other): self
    {
        return new self(bcmul($this->value, $other->value, 2 * self::ROUND_SCALE));
    }

    public function multiplyByInteger(int $factor): self
    {
        return new self(bcmul($this->value, (string) $factor, self::ROUND_SCALE));
    }

    /**
     * Division by an integer, exact when the division is exact (e.g. ÷ 1_000_000
     * of "tokens × rate"): 6 + up to 7 extra digits, fully within scale.
     */
    public function divideByInteger(int $divisor): self
    {
        if ($divisor === 0) {
            throw new \DivisionByZeroError('Division by zero.');
        }

        return new self(bcdiv($this->value, (string) $divisor, self::ROUND_SCALE + 8));
    }

    /**
     * Round to {@see ROUND_SCALE} digits HALF_UP (2.5 → 3), computed on the
     * exact integer-scaled representation — no precision is lost beforehand.
     */
    public function roundTo(int $scale = self::ROUND_SCALE): self
    {
        if ($scale < 0 || $scale > self::ROUND_SCALE) {
            throw new \InvalidArgumentException('Scale out of range.');
        }

        // value * 10^6 as an exact integer string (value has ≤ ROUND_SCALE+8 digits)
        $intValue = bcdiv(
            bcmul($this->value, (string) (new \BCMath\Number('1'))->power(self::ROUND_SCALE)->value, self::ROUND_SCALE + 8),
            '1',
            0,
        );
        $shift = self::ROUND_SCALE - $scale;
        $sign = str_starts_with($intValue, '-') ? '-' : '';
        $mag = ltrim($intValue, '-');

        if ($shift === 0) {
            return new self($sign . $mag);
        }

        $factor = '1' . str_repeat('0', $shift);
        $q = bcdiv($mag, $factor, 0);   // floor — exact for non-negative operands
        $r = bcsub($mag, bcmul($q, $factor, 0), 0);
        // HALF_UP: round up when remainder ≥ factor/2 ⇔ 2·r ≥ factor
        if (bccomp(bcmul($r, '2', 0), $factor, 0) >= 0) {
            $q = bcadd($q, '1', 0);
        }

        return new self($sign . $q);
    }

    public function abs(): self
    {
        return new self(ltrim($this->value, '-'));
    }

    /** Canonical decimal value, e.g. "14.262499". */
    public function toBcString(): string
    {
        return $this->value;
    }

    /** Render with exactly $scale digits after the point. */
    public function format(int $scale = self::ROUND_SCALE): string
    {
        if ($scale < 0 || $scale > \BCMath\Number::SCALE) {
            throw new \InvalidArgumentException('Scale out of range.');
        }
        $rounded = $this->roundTo($scale);
        return $rounded->toBcString() === '0'
            ? str_pad('0.', $scale + 1, '0', STR_PAD_RIGHT)
            : number_format((float) $rounded->toBcString(), $scale, '.', '');
    }

    public function __toString(): string
    {
        return $this->value;
    }
}
EOF
