edits.newText:
/**
 * Round to $scale (≤ {@see ROUND_SCALE}) digits HALF_UP (2.5 → 3),
 * on the exact value — no precision is lost before this step.
 */
public function roundTo(int $scale = self::ROUND_SCALE): self
{
    if ($scale < 0 || $scale > self::ROUND_SCALE) {
        throw new \InvalidArgumentException('Scale out of range.');
    }

    // Value as an exact integer: this->value × 10^ROUND_SCALE, computed in bcmath.
    $power = '1' . str_repeat('0', self::ROUND_SCALE);
    $intValue = rtrim(rtrim(bcadd(bcmul($this->value, $power, self::ROUND_SCALE), '0', 0), '0'), '.') === ''
        ? '0'
        : rtrim(rtrim(bcmul($this->value, $power, self::ROUND_SCALE), '0'), '.');
    // bcmul(x, 10^n) never introduces a fractional part, so the above is integral.
    $sign = str_starts_with($intValue, '-') ? '-' : '';
    $mag = ltrim($intValue, '-');

    $shift = self::ROUND_SCALE - $scale;
    if ($shift === 0) {
        return new self($mag === '' ? '0' : ($sign . $mag));
    }

    $factor = '1' . str_repeat('0', $shift);
    $q = bcdiv($mag, $factor, 0);                // floor — exact, non-negative
    $r = bcsub($mag, bcmul($q, $factor, 0), 0);  // exact remainder
    // HALF_UP: round up when 2·r ≥ factor
    if (bccomp(bcmul($r, '2', 0), $factor, 0) >= 0) {
        $q = bcadd($q, '1', 0);
    }

    if ($q === '0') {
        return self::zero();
    }

    return new self($sign . $q);
}

