 */
public function roundTo(int $scale = self::ROUND_SCALE): self
{
    if ($scale < 0 || $scale > self::ROUND_SCALE) {
        throw new \InvalidArgumentException('Scale out of range.');
    }

    [$sign, $digits] = $this->signAndDigits();
    if (strlen($digits) < self::ROUND_SCALE) {
        $digits .= str_repeat('0', self::ROUND_SCALE - strlen($digits));
    }

    $shift = self::ROUND_SCALE - $scale;
    if ($shift === 0) {
        return new self($this->value);
    }

    $factor = '1' . str_repeat('0', $shift);
    $mag = ltrim($digits, '0');
    $mag = $mag === '' ? '0' : $mag;
    $q = bcdiv($mag, $factor, 0);                // floor — exact, non-negative
    $r = bcsub($mag, bcmul($q, $factor, 0), 0);  // exact remainder
    // HALF_UP: round up when 2·r ≥ factor
    if (bccomp(bcmul($r, '2', 0), $factor, 0) >= 0) {
        $q = bcadd($q, '1', 0);
    }

    if ($q === '0') {
        return self::zero();
    }

    return new self(($sign !== '' ? '-' : '') . $q);
}

