    /**
     * Round to $scale (≤ ROUND_SCALE) fractional digits, HALF_UP (2.5 → 3).
     * Pure digit arithmetic on the exact value — nothing is truncated
     * before the rounding decision.
     */
    public function roundTo(int $scale = self::ROUND_SCALE): self
    {
        if ($scale < 0 || $scale > self::ROUND_SCALE) {
            throw new \InvalidArgumentException('Scale out of range.');
        }

        $sign = str_starts_with($this->value, '-') ? '-' : '';
        $mag = self::canonicalMagnitudes(ltrim($this->value, '-'));
        $mantissa = $mag[0] . $mag[1]; // integer digits + fractional digits, no dot

        // Position in the mantissa where kept digits end (0-based).
        $keepEnd = max(0, strlen($mantissa) - (self::ROUND_SCALE - $scale));
        if ($keepEnd === 0) {
            return self::zero();
        }
        $keep = substr($mantissa, 0, $keepEnd);
        $discarded = substr($mantissa, $keepEnd);

        // HALF_UP: round up when the discarded tail is worth ≥ half a unit
        // of 10^-(keepEnd fractional digits). Equivalent: 2·discarded ≥ 5·10^(tailLen-1)
        if ($discarded !== '' && bccomp(bcmul($discarded, '2', 0), '5' . str_repeat('0', max(0, strlen($discarded) - 1)), 0) >= 0) {
            $keep = bcadd($keep, '1', 0);
        }

        $keep = ltrim($keep, '0');
        if ($keep === '') {
            return self::zero();
        }

        // Re-insert the dot: $scale digits belong to the fractional side.
        $len = strlen($keep);
        $int = $scale === 0 || $len <= $scale ? ($scale === 0 ? $keep : '') : substr($keep, 0, $len - $scale);
        $frac = $scale === 0 ? '' : substr($keep, max(0, $len - $scale));
        if ($int === '') {
            $int = '0';
        }

        return new self($sign . $int . ($frac !== '' ? '.' . $frac : ''));
    }

